var t=`0442-karjalanpaisti`;var i=`world-0442`;var a=`FI`;var o=`northern-europe`;var r=4;var s=186;var l={en:`Karjalanpaisti`,ua:`Карельська печеня`};var u={en:`A traditional dish from Finland, centered on beef chuck, pork shoulder, yellow onion, bay leaf. A measured home-kitchen version organized by cooking step.`,ua:`Традиційна страва кухні країни Фінляндія. Основні складники: яловича лопатка, свиняча лопатка, жовта цибуля, лавровий лист. Домашній варіант із кількостями продуктів за етапами приготування.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`beef-chuck`,500,`g`],[`pork-shoulder`,350,`g`],[`yellow-onion`,180,`g`],[`unsalted-butter`,40,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 150 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 150 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:150,i:[[`water`,650,`ml`],[`allspice-berries`,7,`g`],[`bay-leaf`,2,`leaf`],[`ground-black-pepper`,null,`to_taste`],[`table-salt`,null,`to_taste`]]},{en:`Cook the listed ingredients in simmering water for about 23 minutes until tender; drain well if necessary.`,ua:`Варіть зазначені складники у воді приблизно 23 хвилин до м’якості; за потреби добре злийте воду.`,t:[`boiling`],m:23,i:[[`potato`,600,`g`]]}];var g={slug:t,id:i,country:`FI`,region:o,servings:4,minutes:186,title:l,text:u,steps:d};export{a as country,g as default,i as id,s as minutes,o as region,r as servings,t as slug,d as steps,u as text,l as title};